-- Questões originais: Fernandes e Abreu, Implantando a Governança de TI, 4ª edição, Brasport, 2014.
-- Contexto histórico da edição: COBIT 5, ITIL 2011 e versões de normas nela apresentadas.
-- Não são questões oficiais nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 3: O Modelo de Governança de TI — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('b09ec5bd-0a7c-5ec4-9a36-21477e50e29c', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Governança de TI', 'Fácil', 'O modelo genérico dos autores deve ser implantado de que modo?', '["Sem participação do negócio.","Integralmente em uma única data.","Somente após certificação de todos.","Por cópia do organograma de outra empresa.","Adaptado às necessidades e prioridades da organização."]'::jsonb, 4, 'Os componentes podem ser desenvolvidos progressivamente conforme o contexto.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.1, páginas 61–67 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4f4776a7-dcc8-5cf4-af06-b1a09dac686f', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Governança de TI', 'Fácil', 'Qual transformação caracteriza o alinhamento estratégico de TI?', '["Chamados em contratos societários.","Servidores em objetivos financeiros automaticamente.","Custos em benefícios sem medição.","Auditorias em código-fonte.","Estratégia do negócio em estratégias e ações de TI."]'::jsonb, 4, 'O alinhamento faz a TI apoiar os objetivos empresariais.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.2.1, páginas 67–71 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae5e070f-eef8-5fac-bd22-3ca7dba243f1', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Governança de TI', 'Médio', 'Por que o alinhamento é apresentado como bidirecional?', '["O orçamento é sempre dividido ao meio.","O negócio precisa seguir qualquer preferência técnica.","Existem obrigatoriamente dois planos independentes.","Toda decisão tem dois fornecedores.","A TI também pode viabilizar novas estratégias de negócio."]'::jsonb, 4, 'Capacidades tecnológicas podem criar oportunidades que influenciam a estratégia.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.2.1, páginas 67–71 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e3479106-14bc-5e3a-98b2-9bf77ca700f0', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Governança de TI', 'Fácil', 'Qual é o principal produto da fase de alinhamento no modelo proposto?', '["Ata de manutenção.","Código de um aplicativo.","Relatório exclusivo de chamados.","Plano de Tecnologia da Informação.","Somente inventário físico."]'::jsonb, 3, 'O plano consolida ações, políticas e necessidades derivadas do alinhamento.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.2.2, páginas 71–140 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1a2b55ac-9384-5cbf-ac49-f0e280fc8d3b', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Governança de TI', 'Médio', 'O plano de TI foi elaborado somente para encerrar uma pendência de auditoria. Qual limitação existe?', '["Garante todo o alinhamento.","Dispensa revisões posteriores.","É automaticamente superior ao plano empresarial.","Pode deixar de apoiar a gestão e a estratégia.","Substitui o orçamento aprovado."]'::jsonb, 3, 'O plano deve servir à gestão e à comunicação entre TI e negócio.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.2.2, páginas 71–140 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('17b26989-8969-503c-8785-6a590b46460e', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Governança de TI', 'Médio', 'Uma mudança relevante na estratégia empresarial exige avaliar o quê?', '["A suspensão de todos os controles.","Atualização do plano de TI.","Apenas o nome da equipe.","Somente o papel de parede dos sistemas.","Exclusivamente a marca dos servidores."]'::jsonb, 1, 'O plano deve acompanhar mudanças nas necessidades e orientações do negócio.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.2.2, páginas 71–140 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3aa3ff9d-f251-521c-b314-a274772e303e', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Governança de TI', 'Médio', 'Uma matriz de responsabilidades nas decisões de TI ajuda a definir:', '["Apenas capacidade de armazenamento.","Exclusivamente custos de licenças.","Quem participa e responde por cada decisão.","Somente sequência de testes.","Somente salários de executivos."]'::jsonb, 2, 'Direitos decisórios precisam ser explícitos para evitar lacunas e sobreposições.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.3, páginas 145–147 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f510cc7a-67cb-56ac-87fb-c30d7b5eb644', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Governança de TI', 'Médio', 'A gestão de portfólio deve priorizar projetos de acordo com:', '["Somente preferência do fornecedor.","Ordem alfabética dos projetos.","Valor, riscos e prioridades corporativas.","Apenas influência pessoal do solicitante.","Quantidade de slides apresentados."]'::jsonb, 2, 'A seleção deve refletir o interesse do negócio diante dos recursos disponíveis.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.4.1, páginas 147–149 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6cab3e0c-37bd-5b7c-b2f6-ab0df7d24252', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Governança de TI', 'Fácil', 'Definir canais e compromissos de atendimento trata de qual relacionamento?', '["Somente acionistas com concorrentes.","Apenas fabricantes entre si.","TI com clientes e usuários.","Exclusivamente auditores com reguladores.","Somente RH com sindicatos."]'::jsonb, 2, 'O modelo de relacionamento organiza demanda, atendimento e acompanhamento.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.4.3, páginas 155–158 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5ad7a5c2-2cb7-5c68-a6fb-8aac30a697d1', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Governança de TI', 'Médio', 'Contratar um serviço elimina a necessidade de medir seu fornecedor?', '["Não; desempenho e compromissos devem ser acompanhados.","Sim, se o preço for fixo.","Não, porque contratos de serviço são proibidos.","Sim, quando terceiriza infraestrutura.","Sim, até o fim do contrato."]'::jsonb, 0, 'A gestão do fornecedor continua após a contratação.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.4.4, páginas 158–162 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5405383b-c702-5b11-9439-fc0ac81a278b', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Governança de TI', 'Médio', 'Comparar capacidade disponível e demanda futura apoia qual gestão?', '["Recursos de TI.","Exclusivamente divulgação de resultados.","Somente auditoria externa.","Apenas aprovação societária.","Somente identidade visual."]'::jsonb, 0, 'A alocação precisa considerar capacidade e necessidades do negócio.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.5, páginas 162–164 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fc538813-a45b-5308-a1f1-d3ccb9d55a39', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Governança de TI', 'Médio', 'Um projeto foi entregue, mas seu benefício só pode ser observado meses depois. O que fazer?', '["Substituir benefícios por horas trabalhadas.","Medir o resultado no horizonte adequado.","Excluir o projeto do portfólio retroativamente.","Considerar benefício igual ao gasto.","Encerrar toda avaliação na entrega."]'::jsonb, 1, 'Valor para o negócio pode se materializar após o término do projeto.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.6.2, páginas 174–176 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e62d4367-ccb0-5a33-be3b-05c568a6059b', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Governança de TI', 'Médio', 'Indicadores mostram desvio recorrente de desempenho. Qual providência é coerente?', '["Analisar causas e acompanhar ações corretivas.","Suspender a coleta de dados.","Apenas mudar a cor do painel.","Excluir metas sem análise.","Considerar a medição suficiente por si."]'::jsonb, 0, 'A gestão usa os resultados para orientar melhorias.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.6.4, páginas 192–195 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f2a7328c-4524-55b5-af51-0c3c94ea6fc3', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Governança de TI', 'Fácil', 'Um dashboard executivo deve facilitar principalmente:', '["Substituição automática do CIO.","Entendimento rápido de resultados relevantes.","Exposição indiscriminada de dados.","Leitura de todo log técnico bruto.","Eliminação da comunicação."]'::jsonb, 1, 'O painel seleciona informações úteis para decisões do seu público.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.7, páginas 195–201 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fae17199-9635-5c9b-9cc6-cf1a06352b30', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Governança de TI', 'Médio', 'Por que um mesmo painel pode não atender gestores técnicos e executivos de negócio?', '["Indicadores não podem ser compartilhados.","Gestores técnicos não precisam de metas.","O livro proíbe dashboards múltiplos.","Executivos só podem ver custos.","Os públicos possuem interesses informacionais diferentes."]'::jsonb, 4, 'A comunicação deve ajustar conteúdo e nível de detalhe ao destinatário.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.7, páginas 195–201 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('446730ab-515e-5495-a77b-519c33d0f140', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Governança de TI', 'Médio', 'Implantar processos sem preparar as pessoas compromete especialmente:', '["Exclusivamente o licenciamento.","Apenas o nome do projeto.","A transição e adoção da mudança organizacional.","Somente a largura da rede.","Somente o inventário físico."]'::jsonb, 2, 'A sustentação da governança depende de mudança de comportamentos e práticas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.8, páginas 201–205 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fcad8240-d08c-578e-ad28-63a7914f3e23', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Governança de TI', 'Médio', 'Para avaliar controles com confiança, os avaliadores devem ser:', '["Apenas os autores dos controles.","Dispensados de conhecimento técnico.","Exclusivamente usuários recém-admitidos.","Independentes e qualificados.","Somente fornecedores comerciais."]'::jsonb, 3, 'Independência e competência apoiam uma avaliação confiável.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.9, páginas 205–206 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a41f4072-c116-505d-84d1-a8efe2df36f7', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Governança de TI', 'Médio', 'A avaliação de risco considera normalmente quais dimensões?', '["Probabilidade e impacto.","Exclusivamente quantidade de contratos.","Somente número de empregados.","Apenas idade dos servidores.","Somente custo de auditoria."]'::jsonb, 0, 'As duas dimensões ajudam a estimar exposição e priorizar respostas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.10.1, páginas 206–209 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('48563fb2-ca51-520e-92cb-bd035a5c661f', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Governança de TI', 'Difícil', 'Após aplicar controles, permanece alguma exposição. Como ela é denominada?', '["Custo irrecuperável.","Benefício realizado.","Capacidade nominal.","Risco residual.","Risco inexistente."]'::jsonb, 3, 'O risco residual é o que resta após o tratamento aplicado.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.10.1, páginas 206–209 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f2da3489-bc07-5694-903e-9b70bff2c1a6', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Governança de TI', 'Médio', 'Compliance de TI abrange conformidade com:', '["Somente leis estrangeiras.","Regulamentos internos e externos aplicáveis.","Exclusivamente recomendações informais.","Somente políticas de senha.","Apenas contratos de hardware."]'::jsonb, 1, 'O modelo inclui regras internas e obrigações externas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 3, seção 3.10.2, páginas 209–210 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false)
